public class ExplicacionYEjemplosFor {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
//Sintaxis For
/*
 * for (int i = 1; i<= 10; i++) {
 * declaración e inicialización i++ Incrementos variables
 * 	sysout("Hola");
 * }
 * 
 // Comparación con while 
 * int i = 1;
 * while (i <= 10 ) {
 * sysout("Hola");
 * i++;
 * }
 * 
 // Bucle For curioso
 * for ( j j ) { //Si vale un numero en particular
 * (condicion) {
 * break; //Bucle infinito que se rompe al poner break;
 * }
 * 
 * While Puede nunca ejecutarse
 * Do While Siempre se ejecuta 
 * For Un numero determinado de veces
 * }
 * 
 * En resumen 
 * Usar while cuando la condición depende de un dato que ya existe antes de entrar 
 * al bucle (validación previa).
 * Usar do-while cuando el dato necesario 
 * para la condición se genera dentro del bucle (lectura interactiva con el usuario).
 * 
 */
	}

}
